llm_calls.content:
{
  "task_summary": "Predict whether an ACS person is employed, using person and household attributes that should generalize across states.",
  "ranking": [
    {
      "rank": 1,
      "feature_id": 0,
      "rationale": "Age is a strong, broadly stable predictor of labor force attachment and employment."
    },
    {
      "rank": 2,
      "feature_id": 1,
      "rationale": "Education strongly and consistently relates to employment prospects across states."
    },
    {
      "rank": 3,
      "feature_id": 4,
      "rationale": "Disability status is a durable predictor of employment and not state-specific."
    },
    {
      "rank": 4,
      "feature_id": 2,
      "rationale": "Marital status captures stable household/life-stage differences in employment."
    },
    {
      "rank": 5,
      "feature_id": 3,
      "rationale": "Sex is a persistent demographic correlate of employment, though partly a shortcut."
    },
    {
      "rank": 6,
      "feature_id": 14,
      "rationale": "Cognitive difficulty is a meaningful, general employment barrier across geographies."
    },
    {
      "rank": 7,
      "feature_id": 13,
      "rationale": "Vision difficulty can affect employability in a fairly stable way."
    },
    {
      "rank": 8,
      "feature_id": 12,
      "rationale": "Hearing difficulty is another general functional limitation relevant to employment."
    },
    {
      "rank": 9,
      "feature_id": 10,
      "rationale": "Nativity can matter for labor market access, but may also proxy local immigrant composition."
    },
    {
      "rank": 10,
      "feature_id": 7,
      "rationale": "Citizenship status is predictive of employment eligibility and access, but can be a demographic shortcut."
    },
    {
      "rank": 11,
      "feature_id": 15,
      "rationale": "Race is often predictive in ACS tasks, but much of that signal is structural and potentially brittle across states."
    },
    {
      "rank": 12,
      "feature_id": 11,
      "rationale": "Household relationship can reflect age and family role, but is less directly tied to employment."
    },
    {
      "rank": 13,
      "feature_id": 8,
      "rationale": "Military service status may correlate with employment, but is niche and population-specific."
    },
    {
      "rank": 14,
      "feature_id": 6,
      "rationale": "Recent mobility can capture instability, but is also sensitive to migration patterns that vary by state."
    },
    {
      "rank": 15,
      "feature_id": 9,
      "rationale": "Ancestry is usually a weak proxy and can encode regional or ethnic composition artifacts."
    },
    {
      "rank": 16,
      "feature_id": 16,
      "rationale": "Grandparent-care status is highly specific and only weakly related to employment for most people."
    },
    {
      "rank": 17,
      "feature_id": 5,
      "rationale": "Parental employment status is mainly defined for children and is least relevant for this adult employment task."
    }
  ]
}
